#include <vector>
#include <cstddef>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    int max_deg = 0;

    #pragma omp parallel for reduction(max:max_deg) schedule(static)
    for (size_t i = 0; i < N; ++i) {
        int deg = 0;
        const size_t row_start = i * N;
        for (size_t j = 0; j < N; ++j) {
            deg += A[row_start + j];
        }
        if (deg > max_deg) {
            max_deg = deg;
        }
    }

    return max_deg;
}
